import pathlib
PATCH = {
    'src/main/java/com/example/fpvdrone/event/ClientEvents.java': 'package com.example.fpvdrone.event;\n\nimport com.example.fpvdrone.FpvDroneMod;\nimport com.example.fpvdrone.client.ClientDroneState;\nimport com.example.fpvdrone.client.gui.FpvHudOverlay;\nimport com.example.fpvdrone.client.renderer.FpvDroneRenderer;\nimport com.example.fpvdrone.entity.FpvDroneEntity;\nimport com.example.fpvdrone.network.C2SDroneControlPacket;\nimport com.example.fpvdrone.network.PacketHandler;\nimport com.example.fpvdrone.registry.ModEntities;\nimport com.mojang.blaze3d.vertex.PoseStack;\nimport net.minecraft.client.Minecraft;\nimport net.minecraft.client.player.Input;\nimport net.minecraft.client.renderer.LightTexture;\nimport net.minecraft.client.renderer.MultiBufferSource;\nimport net.minecraft.util.Mth;\nimport net.minecraft.world.phys.Vec3;\nimport net.minecraftforge.api.distmarker.Dist;\nimport net.minecraftforge.client.event.ClientPlayerNetworkEvent;\nimport net.minecraftforge.client.event.EntityRenderersEvent;\nimport net.minecraftforge.client.event.MovementInputUpdateEvent;\nimport net.minecraftforge.client.event.RegisterGuiOverlaysEvent;\nimport net.minecraftforge.client.event.RenderGuiOverlayEvent;\nimport net.minecraftforge.client.event.RenderHandEvent;\nimport net.minecraftforge.client.event.RenderLevelStageEvent;\nimport net.minecraftforge.client.event.ViewportEvent;\nimport net.minecraftforge.event.TickEvent;\nimport net.minecraftforge.eventbus.api.SubscribeEvent;\nimport net.minecraftforge.fml.common.Mod;\nimport org.joml.Quaternionf;\nimport org.joml.Vector3f;\nimport org.lwjgl.glfw.GLFW;\n\n@Mod.EventBusSubscriber(modid = FpvDroneMod.MODID, value = Dist.CLIENT, bus = Mod.EventBusSubscriber.Bus.FORGE)\npublic class ClientEvents {\n    private static final float FPV_CAMERA_UPTILT_RAD = (float) Math.toRadians(18.0D);\n    private static double lastMouseX = Double.NaN;\n    private static double lastMouseY = Double.NaN;\n\n    @SubscribeEvent\n    public static void onClientTick(TickEvent.ClientTickEvent event) {\n        if (event.phase != TickEvent.Phase.END) {\n            return;\n        }\n        ClientDroneState.tick();\n\n        Minecraft mc = Minecraft.getInstance();\n        if (!ClientDroneState.isPiloting() || mc.player == null || mc.screen != null) {\n            lastMouseX = Double.NaN;\n            lastMouseY = Double.NaN;\n            return;\n        }\n\n        long window = mc.getWindow().getWindow();\n\n        // Standard PC FPV Mode-2 controls:\n        // W / Space = Throttle Up, S / Left Shift = Throttle Down\n        // A / D (or Left / Right arrows) = Yaw Left / Right\n        // Mouse Y = Pitch (push forward = nose down), Mouse X = Roll (bank left/right)\n        float throttleDelta = 0.0F;\n        if (mc.options.keyUp.isDown() || mc.options.keyJump.isDown()) {\n            throttleDelta += 1.0F;\n        }\n        if (mc.options.keyDown.isDown() || GLFW.glfwGetKey(window, GLFW.GLFW_KEY_LEFT_SHIFT) == GLFW.GLFW_PRESS) {\n            throttleDelta -= 1.0F;\n        }\n\n        float yawInput = 0.0F;\n        if (mc.options.keyLeft.isDown() || GLFW.glfwGetKey(window, GLFW.GLFW_KEY_LEFT) == GLFW.GLFW_PRESS) {\n            yawInput -= 1.0F;\n        }\n        if (mc.options.keyRight.isDown() || GLFW.glfwGetKey(window, GLFW.GLFW_KEY_RIGHT) == GLFW.GLFW_PRESS) {\n            yawInput += 1.0F;\n        }\n\n        float pitchInput = 0.0F;\n        float rollInput = 0.0F;\n        double currentMouseX = mc.mouseHandler.xpos();\n        double currentMouseY = mc.mouseHandler.ypos();\n        if (!Double.isNaN(lastMouseX) && !Double.isNaN(lastMouseY)) {\n            double dx = currentMouseX - lastMouseX;\n            double dy = currentMouseY - lastMouseY;\n            if (Math.abs(dx) > 0.5D) {\n                rollInput = Mth.clamp((float) (dx * 0.032D), -1.0F, 1.0F);\n            }\n            if (Math.abs(dy) > 0.5D) {\n                // Mouse moved up (dy < 0) => pitch nose down (pitchInput < 0)\n                pitchInput = Mth.clamp((float) (dy * 0.032D), -1.0F, 1.0F);\n            }\n        }\n        lastMouseX = currentMouseX;\n        lastMouseY = currentMouseY;\n\n        PacketHandler.sendToServer(new C2SDroneControlPacket(\n                ClientDroneState.getActiveDroneId(),\n                pitchInput,\n                rollInput,\n                yawInput,\n                throttleDelta\n        ));\n    }\n\n    @SubscribeEvent\n    public static void onMovementInputUpdate(MovementInputUpdateEvent event) {\n        if (ClientDroneState.isPilotingOrTransitioning()) {\n            Input input = event.getInput();\n            input.forwardImpulse = 0.0F;\n            input.leftImpulse = 0.0F;\n            input.up = false;\n            input.down = false;\n            input.left = false;\n            input.right = false;\n            input.jumping = false;\n            input.shiftKeyDown = false;\n        }\n    }\n\n    @SubscribeEvent\n    public static void onRenderHand(RenderHandEvent event) {\n        if (ClientDroneState.isPilotingOrTransitioning()) {\n            event.setCanceled(true);\n        }\n    }\n\n    @SubscribeEvent\n    public static void onRenderGuiOverlayPre(RenderGuiOverlayEvent.Pre event) {\n        if (ClientDroneState.isPilotingOrTransitioning()) {\n            if (!event.getOverlay().id().getNamespace().equals(FpvDroneMod.MODID)) {\n                event.setCanceled(true);\n            }\n        }\n    }\n\n    @SubscribeEvent\n    public static void onRenderLevelStage(RenderLevelStageEvent event) {\n        if (event.getStage() != RenderLevelStageEvent.Stage.AFTER_ENTITIES) {\n            return;\n        }\n        if (!ClientDroneState.isPiloting()) {\n            return;\n        }\n        Minecraft mc = Minecraft.getInstance();\n        if (!mc.options.getCameraType().isFirstPerson()) {\n            return;\n        }\n        if (!(mc.getCameraEntity() instanceof FpvDroneEntity drone)) {\n            return;\n        }\n\n        float partialTick = event.getPartialTick();\n        Vec3 camPos = event.getCamera().getPosition();\n        Vec3 dronePos = drone.getPosition(partialTick);\n\n        PoseStack poseStack = event.getPoseStack();\n        poseStack.pushPose();\n        poseStack.translate(dronePos.x - camPos.x, dronePos.y - camPos.y, dronePos.z - camPos.z);\n\n        MultiBufferSource.BufferSource bufferSource = mc.renderBuffers().bufferSource();\n        mc.getEntityRenderDispatcher().render(\n                drone,\n                0.0D, 0.0D, 0.0D,\n                0.0F,\n                partialTick,\n                poseStack,\n                bufferSource,\n                LightTexture.FULL_BRIGHT\n        );\n        bufferSource.endBatch();\n        poseStack.popPose();\n    }\n\n    @SubscribeEvent\n    public static void onComputeCameraAngles(ViewportEvent.ComputeCameraAngles event) {\n        if (ClientDroneState.getPhase() == ClientDroneState.Phase.FREEZE_FRAME) {\n            event.setYaw(ClientDroneState.getLastCamYaw());\n            event.setPitch(ClientDroneState.getLastCamPitch());\n            event.setRoll(ClientDroneState.getLastCamRoll());\n            return;\n        }\n\n        if (!ClientDroneState.isPiloting()) {\n            return;\n        }\n\n        Minecraft mc = Minecraft.getInstance();\n        if (mc.getCameraEntity() instanceof FpvDroneEntity drone) {\n            // Apply 18-degree FPV camera uptilt in local frame so forward flight keeps horizon & target centered\n            Quaternionf q = drone.getInterpolatedOrientation((float) event.getPartialTick())\n                    .rotateX(-FPV_CAMERA_UPTILT_RAD);\n\n            Vector3f forward = new Vector3f(0.0F, 0.0F, 1.0F).rotate(q);\n            Vector3f localUp = new Vector3f(0.0F, 1.0F, 0.0F).rotate(q);\n            Vector3f localRight = new Vector3f(-1.0F, 0.0F, 0.0F).rotate(q);\n\n            float yaw = (float) Math.toDegrees(Math.atan2(-forward.x, forward.z));\n            float pitch = (float) -Math.toDegrees(Math.asin(Mth.clamp(forward.y, -1.0F, 1.0F)));\n\n            Vector3f worldUp = new Vector3f(0.0F, 1.0F, 0.0F);\n            Vector3f horizonRight = new Vector3f(forward).cross(worldUp);\n            float roll = 0.0F;\n            if (horizonRight.lengthSquared() > 1.0E-5F) {\n                horizonRight.normalize();\n                Vector3f horizonUp = new Vector3f(horizonRight).cross(forward).normalize();\n                roll = (float) Math.toDegrees(Math.atan2(localRight.dot(horizonUp), localRight.dot(horizonRight)));\n            } else {\n                roll = (float) Math.toDegrees(Math.atan2(localUp.x, localUp.z));\n            }\n\n            ClientDroneState.setLastCamAngles(yaw, pitch, roll);\n            event.setYaw(yaw);\n            event.setPitch(pitch);\n            event.setRoll(roll);\n        }\n    }\n\n    @SubscribeEvent\n    public static void onClientLogout(ClientPlayerNetworkEvent.LoggingOut event) {\n        ClientDroneState.resetImmediate();\n    }\n\n    @Mod.EventBusSubscriber(modid = FpvDroneMod.MODID, value = Dist.CLIENT, bus = Mod.EventBusSubscriber.Bus.MOD)\n    public static class ClientModEvents {\n        @SubscribeEvent\n        public static void onRegisterRenderers(EntityRenderersEvent.RegisterRenderers event) {\n            event.registerEntityRenderer(ModEntities.FPV_DRONE.get(), FpvDroneRenderer::new);\n        }\n\n        @SubscribeEvent\n        public static void onRegisterGuiOverlays(RegisterGuiOverlaysEvent event) {\n            event.registerAboveAll("fpv_hud", FpvHudOverlay.HUD_OVERLAY);\n        }\n    }\n}\n',
    'src/main/java/com/example/fpvdrone/client/gui/FpvHudOverlay.java': 'package com.example.fpvdrone.client.gui;\n\nimport com.example.fpvdrone.FpvDroneMod;\nimport com.example.fpvdrone.client.ClientDroneState;\nimport com.example.fpvdrone.entity.FpvDroneEntity;\nimport com.example.fpvdrone.item.FpvGogglesItem;\nimport com.mojang.blaze3d.platform.NativeImage;\nimport com.mojang.blaze3d.systems.RenderSystem;\nimport net.minecraft.client.Minecraft;\nimport net.minecraft.client.Screenshot;\nimport net.minecraft.client.gui.Font;\nimport net.minecraft.client.gui.GuiGraphics;\nimport net.minecraft.client.renderer.texture.DynamicTexture;\nimport net.minecraft.resources.ResourceLocation;\nimport net.minecraft.util.Mth;\nimport net.minecraft.world.entity.EquipmentSlot;\nimport net.minecraftforge.client.gui.overlay.IGuiOverlay;\n\nimport java.util.Random;\n\npublic class FpvHudOverlay {\n    private static final int NOISE_W = 256;\n    private static final int NOISE_H = 144;\n    private static final Random RANDOM = new Random();\n\n    private static DynamicTexture freezeTexture = null;\n    private static ResourceLocation freezeTextureLoc = null;\n\n    private static DynamicTexture staticNoiseTexture = null;\n    private static ResourceLocation staticNoiseLoc = null;\n\n    private static DynamicTexture snowOverlayTexture = null;\n    private static ResourceLocation snowOverlayLoc = null;\n\n    public static void captureFreezeFrame() {\n        Minecraft mc = Minecraft.getInstance();\n        mc.execute(() -> {\n            clearFreezeFrame();\n            NativeImage image = Screenshot.takeScreenshot(mc.getMainRenderTarget());\n            freezeTexture = new DynamicTexture(image);\n            freezeTextureLoc = mc.getTextureManager().register(FpvDroneMod.MODID + "_freeze", freezeTexture);\n        });\n    }\n\n    public static void clearFreezeFrame() {\n        if (freezeTexture != null) {\n            freezeTexture.close();\n            freezeTexture = null;\n            freezeTextureLoc = null;\n        }\n    }\n\n    private static void ensureStaticTexture(Minecraft mc) {\n        if (staticNoiseTexture == null) {\n            staticNoiseTexture = new DynamicTexture(NOISE_W, NOISE_H, false);\n            staticNoiseLoc = mc.getTextureManager().register(FpvDroneMod.MODID + "_static", staticNoiseTexture);\n        }\n        NativeImage pixels = staticNoiseTexture.getPixels();\n        if (pixels != null) {\n            for (int y = 0; y < NOISE_H; y++) {\n                int bandJitter = RANDOM.nextInt(40) - 20;\n                boolean syncBar = (y % 29 == (int) ((System.currentTimeMillis() / 30) % 29));\n                for (int x = 0; x < NOISE_W; x++) {\n                    int g = syncBar ? 230 : Mth.clamp(85 + RANDOM.nextInt(155) + bandJitter, 10, 250);\n                    int abgr = (0xFF << 24) | (g << 16) | (g << 8) | g;\n                    pixels.setPixelRGBA(x, y, abgr);\n                }\n            }\n            staticNoiseTexture.upload();\n        }\n    }\n\n    private static void updateSnowOverlayTexture(Minecraft mc, float strength) {\n        if (snowOverlayTexture == null) {\n            snowOverlayTexture = new DynamicTexture(NOISE_W, NOISE_H, false);\n            snowOverlayLoc = mc.getTextureManager().register(FpvDroneMod.MODID + "_snow", snowOverlayTexture);\n        }\n        NativeImage pixels = snowOverlayTexture.getPixels();\n        if (pixels != null) {\n            float speckleProb = 0.015F + strength * strength * 0.24F;\n            int rollBand1 = (int) ((System.currentTimeMillis() / 18) % NOISE_H);\n            int rollBand2 = (rollBand1 + NOISE_H / 2) % NOISE_H;\n            for (int y = 0; y < NOISE_H; y++) {\n                boolean inRollBand = Math.abs(y - rollBand1) < 3 || (strength > 0.45F && Math.abs(y - rollBand2) < 2);\n                for (int x = 0; x < NOISE_W; x++) {\n                    if (inRollBand && RANDOM.nextFloat() < (0.35F + strength * 0.55F)) {\n                        int g = RANDOM.nextBoolean() ? 235 : 25;\n                        int a = (int) ((0.35F + strength * 0.55F) * 255);\n                        pixels.setPixelRGBA(x, y, (a << 24) | (g << 16) | (g << 8) | g);\n                    } else if (RANDOM.nextFloat() < speckleProb) {\n                        int g = RANDOM.nextBoolean() ? 245 : 15;\n                        int a = (int) ((0.40F + strength * 0.55F) * 255);\n                        pixels.setPixelRGBA(x, y, (a << 24) | (g << 16) | (g << 8) | g);\n                    } else {\n                        pixels.setPixelRGBA(x, y, 0x00000000);\n                    }\n                }\n            }\n            snowOverlayTexture.upload();\n        }\n    }\n\n    public static final IGuiOverlay HUD_OVERLAY = (gui, guiGraphics, partialTick, screenWidth, screenHeight) -> {\n        Minecraft mc = Minecraft.getInstance();\n        if (mc.player == null) {\n            return;\n        }\n\n        ClientDroneState.Phase phase = ClientDroneState.getPhase();\n        if (phase == ClientDroneState.Phase.IDLE) {\n            return;\n        }\n\n        if (phase == ClientDroneState.Phase.FREEZE_FRAME) {\n            if (freezeTextureLoc != null) {\n                RenderSystem.enableBlend();\n                guiGraphics.blit(freezeTextureLoc, 0, 0, 0, 0, screenWidth, screenHeight, screenWidth, screenHeight);\n                RenderSystem.disableBlend();\n            }\n            renderInterference(mc, guiGraphics, screenWidth, screenHeight, 0.85F);\n            return;\n        }\n\n        if (phase == ClientDroneState.Phase.NO_SIGNAL) {\n            ensureStaticTexture(mc);\n            if (staticNoiseLoc != null) {\n                guiGraphics.blit(staticNoiseLoc, 0, 0, 0, 0, screenWidth, screenHeight, screenWidth, screenHeight);\n            } else {\n                guiGraphics.fill(0, 0, screenWidth, screenHeight, 0xFF707070);\n            }\n            renderNoSignalBanner(guiGraphics, mc.font, screenWidth, screenHeight);\n            return;\n        }\n\n        boolean wearingGoggles = mc.player.getItemBySlot(EquipmentSlot.HEAD).getItem() instanceof FpvGogglesItem;\n        if (!wearingGoggles) {\n            return;\n        }\n\n        // Subtle goggle vignette\n        renderGoggleVignette(guiGraphics, screenWidth, screenHeight);\n\n        float distance = ClientDroneState.getDistanceMeters();\n        float interference = Mth.clamp((distance - 50.0F) / 250.0F, 0.0F, 1.0F);\n        if (distance > 300.0F) {\n            interference = 1.0F;\n        }\n\n        if (interference > 0.01F) {\n            renderInterference(mc, guiGraphics, screenWidth, screenHeight, interference);\n        }\n        renderBetaflightOsd(mc, guiGraphics, mc.font, screenWidth, screenHeight, distance, interference);\n    };\n\n    private static void renderGoggleVignette(GuiGraphics g, int w, int h) {\n        int border = 14;\n        g.fill(0, 0, w, border, 0x55000000);\n        g.fill(0, h - border, w, h, 0x55000000);\n        g.fill(0, border, border, h - border, 0x55000000);\n        g.fill(w - border, border, w, h - border, 0x55000000);\n    }\n\n    private static void renderNoSignalBanner(GuiGraphics g, Font font, int w, int h) {\n        String text = "NO SIGNAL";\n        int scale = 3;\n        g.pose().pushPose();\n        g.pose().scale(scale, scale, 1.0F);\n        int tw = font.width(text);\n        int cx = (w / scale - tw) / 2;\n        int cy = (h / scale - font.lineHeight) / 2;\n        g.fill(cx - 8, cy - 4, cx + tw + 8, cy + font.lineHeight + 4, 0xCC000000);\n        g.drawString(font, text, cx, cy, 0xFFFFFFFF, true);\n        g.pose().popPose();\n    }\n\n    private static void renderInterference(Minecraft mc, GuiGraphics g, int w, int h, float strength) {\n        // Real analog snow + rolling sync bars\n        updateSnowOverlayTexture(mc, strength);\n        if (snowOverlayLoc != null) {\n            RenderSystem.enableBlend();\n            guiGraphics.blit(snowOverlayLoc, 0, 0, 0, 0, w, h, w, h);\n            RenderSystem.disableBlend();\n        }\n\n        // Subtle CRT horizontal scanlines\n        int scanAlpha = (int) (18 + strength * 72);\n        int scanColor = (scanAlpha << 24);\n        for (int y = 0; y < h; y += 3) {\n            g.fill(0, y, w, y + 1, scanColor);\n        }\n\n        // Analog VHS/VTX color-bleed horizontal streaks\n        int streakCount = (int) (1 + strength * 6);\n        for (int i = 0; i < streakCount; i++) {\n            int y = RANDOM.nextInt(Math.max(1, h));\n            int x = RANDOM.nextInt(Math.max(1, w / 2));\n            int len = 30 + RANDOM.nextInt(Math.max(1, w / 2));\n            int a = (int) (strength * 95);\n            int col = RANDOM.nextBoolean() ? ((a << 24) | 0x00FF30B0) : ((a << 24) | 0x0020FFE0);\n            g.fill(x, y, Math.min(w, x + len), y + 1, col);\n        }\n\n        // Chromatic aberration edge tint\n        int chromaAlpha = (int) (strength * 55);\n        int edgeW = (int) (3 + strength * 8);\n        g.fill(0, 0, edgeW, h, (chromaAlpha << 24) | 0x00FF2020);\n        g.fill(w - edgeW, 0, w, h, (chromaAlpha << 24) | 0x002060FF);\n    }\n\n    private static void renderBetaflightOsd(Minecraft mc, GuiGraphics g, Font font, int w, int h,\n                                            float distance, float interference) {\n        int cx = w / 2;\n        int cy = h / 2;\n        int osdColor = 0xFFE8FFE8;\n\n        // Artificial horizon & center crosshair\n        float pitchOffset = Mth.clamp(ClientDroneState.getLastCamPitch(), -45.0F, 45.0F);\n        int horizonY = cy + (int) (pitchOffset * 1.2F);\n        g.fill(cx - 42, horizonY, cx - 14, horizonY + 1, osdColor);\n        g.fill(cx + 14, horizonY, cx + 42, horizonY + 1, osdColor);\n        g.fill(cx - 6, cy, cx + 6, cy + 1, 0xFF00FF88);\n        g.fill(cx, cy - 6, cx + 1, cy + 6, 0xFF00FF88);\n\n        // Top-left: Battery Voltage & Signal RSSI\n        String battText = String.format("BAT %.1fV", ClientDroneState.getBatteryVoltage());\n        int battColor = ClientDroneState.getBatteryVoltage() < 13.8F ? 0xFFFF4444 : osdColor;\n        g.drawString(font, battText, 18, 16, battColor, true);\n\n        int rssi = Math.round((1.0F - interference) * 99.0F);\n        g.drawString(font, String.format("RSSI %d%%", rssi), 18, 28, rssi < 25 ? 0xFFFF5555 : osdColor, true);\n\n        // Speed & Altitude\n        double speedKmh = 0.0D;\n        double alt = 0.0D;\n        if (mc.getCameraEntity() instanceof FpvDroneEntity drone) {\n            speedKmh = drone.getDeltaMovement().length() * 20.0D * 3.6D;\n            alt = drone.getY();\n        }\n        g.drawString(font, String.format("SPD %.0f KM/H", speedKmh), 18, 40, osdColor, true);\n        g.drawString(font, String.format("ALT %.0fM", alt), 18, 52, osdColor, true);\n\n        // Top-right: Flight Timer & Distance\n        int totalSec = ClientDroneState.getFlightTicks() / 20;\n        String timerText = String.format("FLT %02d:%02d", totalSec / 60, totalSec % 60);\n        g.drawString(font, timerText, w - font.width(timerText) - 18, 16, osdColor, true);\n\n        String distText = String.format("DIST %.0fm", distance);\n        g.drawString(font, distText, w - font.width(distText) - 18, 28,\n                distance > 300.0F ? 0xFFFF4444 : osdColor, true);\n\n        if (distance > 250.0F && ((System.currentTimeMillis() / 350) % 2 == 0)) {\n            String warn = "LOW RSSI";\n            g.drawString(font, warn, cx - font.width(warn) / 2, 24, 0xFFFF3333, true);\n        }\n\n        // Bottom-left: Throttle %\n        int thrPct = Math.round(ClientDroneState.getThrottle() * 100.0F);\n        g.drawString(font, String.format("THR %d%%", thrPct), 18, h - 26, osdColor, true);\n\n        // Bottom-right: Mode indicator\n        String mode = distance > 300.0F ? "WEAK LINK" : "ACRO ARMED";\n        g.drawString(font, mode, w - font.width(mode) - 18, h - 26,\n                distance > 300.0F ? 0xFFFFAA00 : 0xFF55FF88, true);\n    }\n}\n',
}
for k, v in PATCH.items():
    p = pathlib.Path(k)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(v, encoding="utf-8")
print("Patched", len(PATCH), "files")
